export function verifyToken(token: string, secret: Buffer): Claims {
  const [header, payload, signature] = token.split('.');
  const expected = createHmac('sha256', secret).update(`${header}.${payload}`).digest();
  const given = Buffer.from(signature, 'base64url');
  if (given.length !== expected.length || !timingSafeEqual(given, expected)) {
    throw new AuthError('bad signature');
  }
  const claims = JSON.parse(Buffer.from(payload, 'base64url').toString()) as Claims;
  const now = Math.floor(Date.now() / 1000);
  if (claims.exp + CLOCK_SKEW_SECONDS < now) throw new AuthError('expired');
  return claims;
}
